def get_styles():
    return r"""<style>
:root{--bg:#f5f1e8;--card:#fffdf8;--ink:#152033;--muted:#707987;--line:#e3dccf;--gold:#bd8012;--green:#16a36a;--red:#df5b5b;--blue:#397bd1;--purple:#7664d8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,Segoe UI,Arial,sans-serif}.mp-app{display:flex;min-height:100vh;background:linear-gradient(135deg,#f4f0e7,#fffdf9)}.mp-sidebar{width:220px;background:#fbfaf6;border-right:1px solid var(--line);padding:20px 12px;position:sticky;top:0;height:100vh}.mp-brand{display:flex;gap:9px;align-items:center;margin:5px 7px 20px}.mp-brand-mark{width:37px;height:37px;border-radius:10px;background:#bd8012;color:white;display:grid;place-items:center}.mp-brand strong{font-size:20px}.mp-brand span{display:block;font-size:8px;color:#888;letter-spacing:1px}.mp-login-mini,.mp-profile-button{width:100%;border:1px solid var(--line);background:#fff;border-radius:10px;padding:9px;cursor:pointer}.mp-nav{display:flex;flex-direction:column;gap:3px;margin-top:12px}.mp-nav a{padding:9px;color:#5d6878;text-decoration:none;border-radius:8px;font-size:13px}.mp-nav a:hover{background:#f1eadc;color:#7c5608}.mp-nav-label{font-size:9px;letter-spacing:1.4px;color:#999;margin:22px 8px 6px}.mp-sidebar-bottom{position:absolute;bottom:16px;left:12px;right:12px}.mp-avatar{display:inline-grid;place-items:center;width:29px;height:29px;border-radius:50%;background:#17263b;color:#fff}.mp-main{flex:1;min-width:0}.mp-topbar{height:70px;display:flex;align-items:center;gap:15px;padding:10px 24px;border-bottom:1px solid var(--line);background:#fffdf9;position:sticky;top:0;z-index:10}.mp-search{flex:1;max-width:500px;background:#f1eee7;border:1px solid var(--line);border-radius:22px;padding:11px 15px}.mp-search input{border:0;background:none;outline:0;width:90%}.mp-indexes{display:flex;gap:20px;margin-left:auto}.mp-indexes div{font-size:9px}.mp-indexes strong{display:block;font-size:13px}.mp-indexes em{color:var(--green);font-style:normal}.mp-user-chip{width:35px;height:35px;border:0;border-radius:50%;background:#18263a;color:#fff}.mp-content{padding:22px;max-width:1550px;margin:auto}.mp-hero{padding:25px 30px;border:1px solid #e2d8c6;border-radius:17px;background:linear-gradient(100deg,#fffdf8,#f4ead6);display:flex;justify-content:space-between;align-items:center;margin-bottom:13px}.mp-eyebrow,.mp-label{font-size:9px;letter-spacing:1.3px;color:#a06d0d;font-weight:800}.mp-hero h1{font-size:29px;margin:7px 0}.mp-hero p{color:var(--muted);margin:0}.mp-bull{padding:12px 16px;border:1px solid #e7d7b9;border-radius:11px;background:#fffaf0;color:#79550e}.mp-feature-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:11px}.mp-feature,.mp-card{background:rgba(255,253,249,.94);border:1px solid var(--line);border-radius:15px;box-shadow:0 6px 20px #3c3a3209}.mp-feature{height:145px;padding:15px;position:relative;overflow:hidden}.mp-feature-icon{width:34px;height:34px;border-radius:9px;background:#f0eadc;display:grid;place-items:center;font-weight:bold}.mp-feature h2{font-size:17px;margin:7px 0 2px}.mp-feature p{font-size:10px;color:var(--muted)}.mp-feature button{position:absolute;right:12px;bottom:11px;border:1px solid var(--line);background:white;border-radius:50%;width:30px;height:30px}.mp-visual{position:absolute;right:15px;bottom:27px;color:#c79632;font-size:24px;letter-spacing:-5px}.mp-dashboard-grid{display:grid;grid-template-columns:1.2fr 1fr 1fr 1fr;gap:11px;margin-top:11px}.mp-card{padding:16px;min-width:0}.mp-card h2{font-size:16px;margin:5px 0 12px}.mp-big{font-size:25px;font-weight:800}.mp-big em{font-size:11px;color:var(--green);font-style:normal}.mp-chart{height:110px;margin-top:8px;color:#19a86e;font-size:30px;letter-spacing:4px;padding-top:35px;border-bottom:2px solid #20a97055}.mp-sent{display:flex;align-items:center;gap:15px}.donut{width:100px;height:100px;border-radius:50%;background:conic-gradient(#18a66b 0 72%,#df5b5b 72% 90%,#cbd0d4 90%);display:grid;place-items:center;font-weight:800;position:relative}.donut:after{content:"";position:absolute;inset:20px;background:#fffdf8;border-radius:50%}.donut{z-index:0}.donut::before{content:"72%";position:absolute;z-index:2}.mp-list p{display:flex;justify-content:space-between;border-bottom:1px solid #eeeae2;padding:7px 0;margin:0;font-size:10px}.mp-list em,.up{color:var(--green);font-style:normal}.mp-list i,.down{color:var(--red);font-style:normal}.alloc{display:flex;align-items:center;gap:15px;font-size:10px}.pie{width:110px;height:110px;border-radius:50%;background:conic-gradient(#397bd1 0 35%,#16a36a 35% 65%,#d9a62f 65% 85%,#7664d8 85% 95%,#df5b5b 95%)}.pnl{margin-top:12px;background:#f5f2eb;padding:8px;border-radius:8px;font-size:10px}.pnl b{color:var(--green)}.mp-bottom-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin-top:11px}.mp-table p{display:grid;grid-template-columns:1fr auto auto;gap:8px;font-size:10px;border-bottom:1px solid #eeeae2;padding:7px 0}.mp-card>p{font-size:10px;border-bottom:1px solid #eeeae2;padding:7px 0}.mp-auth-overlay{display:none;position:fixed;inset:0;background:#15203366;backdrop-filter:blur(4px);z-index:100;align-items:center;justify-content:center}.mp-auth-overlay.open{display:flex}.mp-auth-modal{width:400px;max-width:94%;background:#fffdf8;border:1px solid var(--line);border-radius:18px;padding:25px;position:relative;box-shadow:0 25px 70px #0002}.mp-auth-close{position:absolute;right:12px;top:8px;border:0;background:none;font-size:25px}.auth-brand{color:#a06d0d}.mp-auth-modal h2{margin:7px 0}.mp-auth-modal p{color:var(--muted);font-size:12px}.auth-tabs{display:grid;grid-template-columns:1fr 1fr;background:#f0ede5;padding:3px;border-radius:9px;margin:15px 0}.auth-tabs button{border:0;padding:8px;border-radius:7px;background:transparent}.auth-tabs button:first-child{background:#fff}.mp-auth-modal form{display:grid;gap:7px}.mp-auth-modal label{font-size:10px;font-weight:700}.mp-auth-modal input{height:40px;border:1px solid var(--line);border-radius:8px;padding:0 10px}.mp-auth-modal form button{height:40px;border:0;border-radius:8px;background:#bd8012;color:#fff;margin-top:7px;cursor:pointer}.mp-auth-modal form button[type=button]{background:#edf2f7;color:#2d4964}.mp-auth-modal small{color:#8a8f98;font-size:9px}.mp-auth-modal #auth-msg{font-size:10px;color:#b45d38;margin-top:8px}@media(max-width:1100px){.mp-sidebar{width:185px}.mp-indexes{display:none}.mp-feature-grid,.mp-dashboard-grid,.mp-bottom-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.mp-sidebar{display:none}.mp-content{padding:12px}.mp-feature-grid,.mp-dashboard-grid,.mp-bottom-grid{grid-template-columns:1fr}.mp-topbar{padding:9px 12px}}
</style>"""
